/**
 * @brief Extract an ASCII string literal supported by the byte-based evaluator.
 *
 * @param operand Operand to inspect.
 * @param[out] length Byte length of the string literal.
 * @return Borrowed string, or NULL if the operand cannot be evaluated here.
 */
static const char* ascii_string(IrOperand operand, size_t* length) {
  if (operand.type != IR_OP_STRING)
    return NULL;

  const char* string = operand.value.string_value;
  // For ASCII, byte offsets and character indices are interchangeable.
  *length = strlen(string);
  for (size_t i = 0; i < *length; i++) {
    if ((unsigned char)string[i] > 127)
      return NULL;
  }

  return string;
}

bool optimizer_fold_builtin(Ctx* ctx,
                            const IrInstruction* inst,
                            IrOperand* result) {
  const IrOperand* args = inst->operands.call.args;
  size_t length = 0;
  const char* string = args ? ascii_string(args[0], &length) : NULL;
  if (args && args[0].type == IR_OP_STRING && !string)
    return false;

  switch (inst->operands.call.type) {
    // AI generated by: Codex (GPT-6.2-sol)
    // Prompt: "Implement all"
    // Changes: Fold a negative ord index even when the string is dynamic.
    case IR_FX_ORD: {
      if (args[1].type != IR_OP_INT32)
        return false;

      IrInt index = args[1].value.int32_value;

      // Ord of a negative index is always -1.
      if (index < 0) {
        *result = (IrOperand){IR_OP_INT32, {.int32_value = -1}};
        return true;
      }

      if (!string)
        return false;

      // Ord of an index out of bounds is always -1.
      if ((size_t)index >= length) {
        *result = (IrOperand){IR_OP_INT32, {.int32_value = -1}};
        return true;
      }

      // Ord of a valid index is the character code at that position.
      *result = (IrOperand){IR_OP_INT32, {.int32_value = string[index]}};
      return true;
    }

    case IR_FX_CHR: {
      if (args[0].type != IR_OP_INT32)
        return false;

      IrInt code = args[0].value.int32_value;
      if (code <= 0 || code > 127)
        return false;  // TODO: Throw runtime error 58

      // Convert the integer code to a character and return it as a string.
      char* character = TRY_MALLOC(2);
      character[0] = (char)code;
      character[1] = '\0';
      *result = (IrOperand){IR_OP_STRING, {.string_value = character}};
      return true;
    }

    case IR_FX_STR_SUB: {
      if (!string || args[1].type != IR_OP_INT32 || args[2].type != IR_OP_INT32)
        return false;

      IrInt start = args[1].value.int32_value;
      IrInt end = args[2].value.int32_value;

      if (start < 0 || start > end || (size_t)end > length ||
          (size_t)start >= length)
        return false;  // TODO: Throw runtime error 40

      // Compute the substring and return it as a string.
      size_t count = (size_t)(end - start);
      char* substring = TRY_MALLOC(count + 1);
      memcpy(substring, string + start, count);
      substring[count] = '\0';
      *result = (IrOperand){IR_OP_STRING, {.string_value = substring}};
      return true;
    }

    default:
      return false;
  }
}

// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Ok, implement all, remove things made redundant by this change"
// Changes: Evaluate typed operations independently of the checked call folder.
bool optimizer_fold_builtin_operation(Ctx* ctx,
                                      IrInstructionType type,
                                      IrOperand operand,
                                      IrOperand* result) {
  switch (type) {
    case IR_INST_STR_LEN: {
      size_t length = 0;
      const char* string = ascii_string(operand, &length);
      if (!string || length > INT32_MAX)
        return false;
      *result = (IrOperand){IR_OP_INT32, {.int32_value = (IrInt)length}};
      return true;
    }

    case IR_INST_TO_INT: {
      if (operand.type != IR_OP_DOUBLE)
        return false;
      double value = trunc(operand.value.double_value);
      if (!isfinite(value) || value < INT32_MIN || value > INT32_MAX)
        return false;
      *result = (IrOperand){IR_OP_INT32, {.int32_value = (IrInt)value}};
      return true;
    }

    case IR_INST_INT_TO_STR:
    case IR_INST_DOUBLE_TO_STR:
    case IR_INST_BOOL_TO_STR: {
      char formatted[384];
      const char* text;
      switch (operand.type) {
        case IR_OP_INT32:
          snprintf(formatted, sizeof(formatted), "%" PRId64,
                   operand.value.int32_value);
          text = formatted;
          break;
        // AI generated by: Codex (GPT-6.2-sol)
        // Prompt: "Implement all"
        // Changes: Use the specified IFJ26 two-decimal formatting for finite
        // doubles.
        case IR_OP_DOUBLE: {
          if (!isfinite(operand.value.double_value))
            return false;
          int length = snprintf(formatted, sizeof(formatted), "%.2f",
                                operand.value.double_value);
          if (length < 0 || (size_t)length >= sizeof(formatted))
            return false;
          text = formatted;
          break;
        }
        case IR_OP_BOOL:
          text = operand.value.bool_value ? "true" : "false";
          break;
        default:
          return false;
      }
      *result =
          (IrOperand){IR_OP_STRING, {.string_value = copy_string(ctx, text)}};
      return true;
    }

    default:
      return false;
  }
}
